-- ============================================================
-- FILE: config/init.sql
-- FUNGSI: Inisialisasi database SPK EV AHP TOPSIS
-- Total Data EV: 478 kendaraan listrik
-- Sumber data  : ev-database.org (ev_fixed.sql)
-- Cara pakai   : Import file ini di phpMyAdmin
--                atau jalankan: mysql -u root -p < init.sql
-- ============================================================

-- Buat database
CREATE DATABASE IF NOT EXISTS spk_ev_db
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE spk_ev_db;

-- ============================================================
-- TABEL: users
-- ============================================================
CREATE TABLE IF NOT EXISTS users (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    email       VARCHAR(150) UNIQUE NOT NULL,
    password    VARCHAR(255) NOT NULL,
    role        ENUM('user','admin') DEFAULT 'user',
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: kendaraan_ev
-- Kolom sesuai data asli ev_fixed.sql
-- ============================================================
CREATE TABLE IF NOT EXISTS kendaraan_ev (
    id                      INT AUTO_INCREMENT PRIMARY KEY,
    brand                   VARCHAR(20)  NOT NULL,
    model                   VARCHAR(60)  NOT NULL,
    top_speed_kmh           INT          NOT NULL,
    battery_capacity_kwh    DECIMAL(5,1) NOT NULL,
    battery_type            VARCHAR(20)  NOT NULL,
    number_of_cells         INT          DEFAULT NULL,
    torque_nm               INT          DEFAULT NULL,
    efficiency_wh_per_km    INT          NOT NULL,
    range_km                INT          NOT NULL,
    acceleration_0_100_s    DECIMAL(4,1) NOT NULL,
    fast_charging_power_kw  INT          DEFAULT NULL,
    fast_charge_port        VARCHAR(10)  DEFAULT NULL,
    towing_capacity_kg      INT          DEFAULT NULL,
    cargo_volume_l          VARCHAR(20)  DEFAULT NULL,
    seats                   INT          NOT NULL,
    drivetrain              VARCHAR(5)   NOT NULL,
    segment                 VARCHAR(20)  NOT NULL,
    length_mm               INT          NOT NULL,
    width_mm                INT          NOT NULL,
    height_mm               INT          NOT NULL,
    car_body_type           VARCHAR(25)  NOT NULL,
    source_url              VARCHAR(100) NOT NULL,
    status                  ENUM('aktif','nonaktif') DEFAULT 'aktif',
    created_at              TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_brand       (brand),
    INDEX idx_segment     (segment),
    INDEX idx_drivetrain  (drivetrain),
    INDEX idx_range       (range_km),
    INDEX idx_body        (car_body_type),
    INDEX idx_seats       (seats),
    INDEX idx_status      (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: kriteria
-- ============================================================
CREATE TABLE IF NOT EXISTS kriteria (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    kode            VARCHAR(10)  UNIQUE NOT NULL,
    nama            VARCHAR(100) NOT NULL,
    kolom_db        VARCHAR(60)  NOT NULL,
    tipe            ENUM('benefit','cost') NOT NULL DEFAULT 'benefit',
    bobot_default   DECIMAL(6,4) DEFAULT 0.2000,
    satuan          VARCHAR(20),
    deskripsi       TEXT,
    aktif           TINYINT(1) DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: matriks_ahp
-- Menyimpan nilai perbandingan berpasangan per user
-- ============================================================
CREATE TABLE IF NOT EXISTS matriks_ahp (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id         INT NOT NULL,
    kriteria_i      VARCHAR(10) NOT NULL,
    kriteria_j      VARCHAR(10) NOT NULL,
    nilai           DECIMAL(10,6) NOT NULL DEFAULT 1.000000,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE KEY uq_user_pair (user_id, kriteria_i, kriteria_j)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: bobot_ahp
-- Menyimpan hasil bobot prioritas AHP per user
-- ============================================================
CREATE TABLE IF NOT EXISTS bobot_ahp (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id         INT NOT NULL,
    kriteria_id     INT NOT NULL,
    bobot           DECIMAL(10,8) NOT NULL,
    lambda_max      DECIMAL(12,8) DEFAULT NULL,
    ci              DECIMAL(12,8) DEFAULT NULL,
    cr              DECIMAL(12,8) DEFAULT NULL,
    konsisten       TINYINT(1) DEFAULT NULL,
    updated_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
    FOREIGN KEY (kriteria_id)REFERENCES kriteria(id) ON DELETE CASCADE,
    UNIQUE KEY uq_user_kriteria (user_id, kriteria_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: preferensi_user
-- Menyimpan filter preferensi kendaraan tiap user
-- ============================================================
CREATE TABLE IF NOT EXISTS preferensi_user (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id         INT NOT NULL UNIQUE,
    filter_segment  VARCHAR(25)  DEFAULT NULL,
    filter_drive    VARCHAR(5)   DEFAULT NULL,
    filter_body     VARCHAR(25)  DEFAULT NULL,
    filter_seats    INT          DEFAULT NULL,
    jumlah_alt      INT          DEFAULT 20,
    updated_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- TABEL: history_perhitungan
-- Menyimpan setiap sesi perhitungan AHP-TOPSIS
-- ============================================================
CREATE TABLE IF NOT EXISTS history_perhitungan (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id         INT NOT NULL,
    nama_sesi       VARCHAR(100),
    filter_json     TEXT,
    bobot_json      TEXT,
    ahp_json        TEXT,
    topsis_json     TEXT,
    ranking_json    TEXT,
    cr_value        DECIMAL(10,8) DEFAULT NULL,
    konsisten       TINYINT(1)    DEFAULT NULL,
    jumlah_alt      INT           DEFAULT NULL,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_user_id  (user_id),
    INDEX idx_created  (created_at),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

